import os,re,collections

root='.'
def gofiles(skip_tests=True):
    for dp,dn,fn in os.walk(root):
        if any(p in dp for p in ('./web','./proto/gen','/node_modules')): continue
        for f in fn:
            if not f.endswith('.go'): continue
            if skip_tests and f.endswith('_test.go'): continue
            yield os.path.join(dp,f)

# 1. collect package-level exported funcs in internal/, mapped to package name
decls=[]  # (pkgname, funcname, path)
methods=[] # (recvtype, name, path)
pkgof={}
for path in gofiles():
    if not path.startswith('./internal/'): continue
    src=open(path).read()
    m=re.search(r'^package (\w+)',src,re.M)
    pkg=m.group(1) if m else '?'
    for mm in re.finditer(r'^func\s+(\(([^)]*)\)\s+)?([A-Za-z_]\w*)\s*\(',src,re.M):
        recv=mm.group(2); name=mm.group(3)
        if name=='init': continue
        if recv:
            rt=recv.split()[-1].lstrip('*')
            methods.append((rt,name,path))
        else:
            decls.append((pkg,name,path))

allsrc={p:open(p).read() for p in gofiles()}

res=[]
for pkg,name,path in decls:
    pat=re.compile(r'(?<![A-Za-z0-9_.])'+pkg+r'\.'+name+r'\s*\(')
    tot=0; files=set()
    for p,s in allsrc.items():
        c=len(pat.findall(s))
        if c: tot+=c; files.add(p)
    # also same-package unqualified calls
    pat2=re.compile(r'(?<![A-Za-z0-9_.])'+name+r'\s*\(')
    for p,s in allsrc.items():
        if not p.startswith('./internal/'): continue
        if re.search(r'^package '+pkg+r'\b',s,re.M) and p!=None:
            c=len(pat2.findall(s))
            # subtract declaration
            d=len(re.findall(r'^func\s+'+name+r'\s*\(',s,re.M))
            if c-d>0: tot+=c-d; files.add(p)
    res.append((tot,len(files),pkg+'.'+name,path))

res.sort(reverse=True)
print("== package-level funcs in internal/ (qualified+intra-package) ==")
for r in res[:20]: print(r)

res2=[]
for rt,name,path in methods:
    pat=re.compile(r'\.'+name+r'\s*\(')
    tot=0; files=set()
    for p,s in allsrc.items():
        c=len(pat.findall(s))
        if c: tot+=c; files.add(p)
    res2.append((tot,len(files),rt+'.'+name,path))
res2.sort(reverse=True)
print("== methods (name-based .Name( , upper bound) ==")
for r in res2[:20]: print(r)
EOF
